package tools; import rules.*;import core.Diagnostics;import java.util.List; public final class RuleCheck{public static void main(String[] args){try{List<IdsRule> rules=new RuleParser().parseText(CliSupport.readText(args)).orNull();Diagnostics d=new RuleValidator().validate(rules);RuleNormalizer n=new RuleNormalizer();System.out.println(new RuleSummary().summarize(rules));System.out.print(d.render());for(IdsRule r:rules)System.out.println(n.normalize(r));}catch(Exception e){CliSupport.exitOnError(e);}}}
